const kp = (info, v) => (Array.isArray(v) ? v.map(([a, b]) => [T(info, a, 0), b]) : [[0, v]]);
const at = (info, ks, t) => { let cur = ks[0][1]; for (const [a, b] of ks) if (t >= a) cur = b; return cur; };
const P = (n) => (typeof n === 'string' ? (n === 'crawl' ? null : POSES[n]) : n);
