export function card(g, k, s = 1, lab, o = {}) { g.save(); g.scale(s, s); rr(g, -110, -110, 220, 220, 28); g.fillStyle = '#ffffff'; g.fill(); g.strokeStyle = INK; g.lineWidth = 6; g.stroke(); icon(g, k, 0.85, o); if (lab) { const lw = measure(g, lab, 34, FONTS.ui, 900) + lab.length * 2 + 40; rr(g, -lw / 2, 124, lw, 52, 26); g.fillStyle = '#ffffff'; g.fill(); text(g, lab, 0, 151, { size: 34, color: INK, font: FONTS.ui, weight: 900, spacing: 2 }); } g.restore(); }
