const fit = (g, str, size, maxW, font = FONTS.title, wt = 700) => Math.min(size, size * maxW / Math.max(1, measure(g, str, size, font, wt)));
export function popT(g, k, x, y, fn) { if (k <= 0) return; g.save(); g.translate(x, y); g.scale(k, k); fn(g); g.restore(); }
function pill(g, str, x, y, o = {}) { const sz = o.size || 44; g.save(); g.font = `900 ${sz}px ${FONTS.ui}`; const w = g.measureText(str).width + sz * 1.4 + str.length * 3.2; g.restore(); rr(g, x - w / 2, y - sz * 0.95, w, sz * 1.9, sz * 0.95); g.fillStyle = o.bg || INK; g.fill(); text(g, str, x, y + 3, { size: sz, color: o.col || '#ffffff', font: FONTS.ui, weight: 900, spacing: 3 }); }
